import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.junit.jupiter.api.Test;

class HashJoinBindingContractTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void separatesAssuredLookupBindingsFromPossibleCompatibilityBindings() {
		LeftJoin left = new LeftJoin(pattern("key", "leftOnly"), pattern("key", "nullable"));
		LeftJoin right = new LeftJoin(pattern("key", "rightOnly"), pattern("key", "nullable"));

		HashJoinBindingContract contract = HashJoinBindingContract.from(left, right);

		assertEquals(List.of("key"), contract.lookupBindings());
		assertEquals(List.of("key", "nullable"), contract.compatibilityBindings());
		assertTrue(contract.hasLookupBindings());
	}

	@Test
	void excludesSyntheticConstantsAndUsesDeterministicOrdering() {
		HashJoinBindingContract contract = HashJoinBindingContract.from(
				new StreamBindingSchema(Set.of("z", "a", "_const_left"), Set.of("z", "a", "_const_left")),
				new StreamBindingSchema(Set.of("a", "z", "_const_right"), Set.of("a", "z", "_const_right")));

		assertEquals(List.of("a", "z"), contract.lookupBindings());
		assertEquals(List.of("a", "z"), contract.compatibilityBindings());
	}

	@Test
	void unionOnlyAssuresBindingsProducedByEveryBranch() {
		Union left = new Union(pattern("key", "branchA"), pattern("key", "branchB"));
		Union right = new Union(pattern("key", "branchA"), pattern("key", "branchB"));

		HashJoinBindingContract contract = HashJoinBindingContract.from(left, right);

		assertEquals(List.of("key"), contract.lookupBindings());
		assertEquals(List.of("branchA", "branchB", "key"), contract.compatibilityBindings());
	}

	@Test
	void noAssuredSharedBindingProducesCompatibilityOnlyContract() {
		HashJoinBindingContract contract = HashJoinBindingContract.from(
				new StreamBindingSchema(Set.of("nullable"), Set.of()),
				new StreamBindingSchema(Set.of("nullable"), Set.of()));

		assertTrue(contract.lookupBindings().isEmpty());
		assertEquals(List.of("nullable"), contract.compatibilityBindings());
		assertFalse(contract.hasLookupBindings());
	}

	@Test
	void projectionExtensionAndGroupingPreserveTheirOwnAssuranceRules() {
		Projection leftProjection = new Projection(pattern("leftEntity", "leftValue"),
				new ProjectionElemList(new ProjectionElem("leftValue", "shared")));
		Projection rightProjection = new Projection(pattern("rightEntity", "rightValue"),
				new ProjectionElemList(new ProjectionElem("rightValue", "shared")));
		assertContract(leftProjection, rightProjection, List.of("shared"), List.of("shared"));

		Extension leftExtension = new Extension(pattern("leftEntity", "leftValue"),
				new ExtensionElem(new Var("leftValue"), "shared"));
		Extension rightExtension = new Extension(pattern("rightEntity", "rightValue"),
				new ExtensionElem(new Var("rightValue"), "shared"));
		assertContract(leftExtension, rightExtension, List.of("shared"), List.of("shared"));

		Group leftGroup = new Group(pattern("shared", "leftValue"), List.of("shared"),
				List.of(new GroupElem("count", new Count(new Var("leftValue"), false))));
		Group rightGroup = new Group(pattern("shared", "rightValue"), List.of("shared"),
				List.of(new GroupElem("count", new Count(new Var("rightValue"), false))));
		assertContract(leftGroup, rightGroup, List.of("shared"), List.of("count", "shared"));
	}

	@Test
	void bindingSetAssignmentsKeepNullableBindingsOutOfTheLookupKey() {
		BindingSetAssignment left = assignment("left");
		BindingSetAssignment right = assignment("right");

		assertContract(left, right, List.of("shared"), List.of("nullable", "shared"));
	}

	@Test
	void nestedJoinsKeepOptionalBindingsForCompatibilityOnly() {
		TupleExpr left = new Join(
				new LeftJoin(pattern("shared", "leftOnly"), pattern("shared", "nullable")),
				pattern("shared", "nested"));
		TupleExpr right = new Join(
				new LeftJoin(pattern("shared", "rightOnly"), pattern("shared", "nullable")),
				pattern("shared", "nested"));

		assertContract(left, right, List.of("nested", "shared"),
				List.of("nested", "nullable", "shared"));
	}

	@Test
	void legacyContractDropsReservedNames() {
		HashJoinBindingContract contract = HashJoinBindingContract
				.legacy(new String[] { "shared", "_const_type", "shared" });

		assertEquals(List.of("shared"), contract.lookupBindings());
		assertEquals(List.of("shared"), contract.compatibilityBindings());
	}

	private static BindingSetAssignment assignment(String suffix) {
		QueryBindingSet complete = new QueryBindingSet();
		complete.addBinding("shared", VF.createIRI("urn:shared:" + suffix));
		complete.addBinding("nullable", VF.createLiteral(suffix));
		QueryBindingSet partial = new QueryBindingSet();
		partial.addBinding("shared", VF.createIRI("urn:shared:" + suffix + ":partial"));
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("shared", "nullable"));
		assignment.setBindingSets(List.of(complete, partial));
		return assignment;
	}

	private static void assertContract(TupleExpr left, TupleExpr right, List<String> lookup,
			List<String> compatibility) {
		HashJoinBindingContract contract = HashJoinBindingContract.from(left, right);
		assertEquals(lookup, contract.lookupBindings());
		assertEquals(compatibility, contract.compatibilityBindings());
	}

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(new Var(subject),
				Var.of("_const_predicate", VF.createIRI("urn:predicate"), false, true),
				new Var(object));
	}
}
